<script setup lang="ts">
import { computed } from "vue"; import { BarChart3, CalendarDays, CheckCircle2, ChevronRight, Download, MoreVertical, PlusCircle, ShieldCheck, TriangleAlert } from "lucide-vue-next"; import { useI18n } from "vue-i18n";
import CropHistoryImage from "./CropHistoryImage.vue"; import type { DiagnosisHistoryItem } from "@/features/history/types/history";
const props = defineProps<{ item: DiagnosisHistoryItem }>(); const emit = defineEmits<{ open: []; follow: []; export: [] }>(); const { t, locale } = useI18n();
const statusLabel = computed(() => t(`history.${props.item.status === 'follow_up' ? 'followUp' : props.item.status === 'completed' ? 'done' : props.item.status === 'draft' ? 'draft' : 'watch'}`));
const date = computed(() => new Intl.DateTimeFormat(locale.value, { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(props.item.createdAt)));
const followText = computed(() => { if (!props.item.nextFollowUpAt) return ""; const days = Math.max(0, Math.ceil((+new Date(props.item.nextFollowUpAt) - Date.now()) / 86400000)); return days === 0 ? t("history.todayDue") : days === 1 ? t("history.tomorrow") : t("history.inDays", { days }); });
</script>
<template><article class="history-card" :class="{ featured: item.status === 'follow_up' }"><div class="history-crop"><CropHistoryImage :crop="item.crop" /></div><div class="min-w-0"><h3>{{ t(`history.${item.crop}`) }}</h3><p class="diagnosis-name">{{ item.summary }}</p><div class="mt-3 flex flex-wrap gap-2"><span v-if="item.confidence" class="confidence"><BarChart3 />{{ t('history.confidence') }} : {{ item.confidence }} %</span><span class="status" :class="item.status"><ShieldCheck v-if="item.status !== 'watch'" /><TriangleAlert v-else />{{ statusLabel }}</span></div><p class="created"><CalendarDays />{{ t('history.created') }} {{ date }}</p></div><div class="history-follow"><template v-if="item.nextFollowUpAt"><p><CalendarDays />{{ t('history.nextObservation') }}</p><strong>{{ followText }}</strong></template><template v-else-if="item.status === 'completed'"><p><CheckCircle2 />{{ t('history.done') }}</p></template><div v-if="item.totalActions" class="action-progress"><span>{{ item.completedActions }} / {{ item.totalActions }} {{ t('history.actionsCompleted') }}</span><div><i v-for="n in Math.min(item.totalActions, 10)" :key="n" :class="{ complete: n <= item.completedActions }" /></div></div></div><div class="history-buttons"><button class="primary" @click="emit('open')">{{ item.status === 'completed' ? t('history.consult') : t('history.open') }}<ChevronRight /></button><button v-if="item.status !== 'completed'" @click="emit('follow')"><PlusCircle />{{ t('history.addFollowUp') }}</button><button v-else @click="emit('export')"><Download />{{ t('history.export') }}</button></div><button class="more" aria-label="Menu"><MoreVertical /></button></article></template>

<style scoped>
.history-card{position:relative;display:grid;grid-template-columns:170px minmax(240px,1.25fr) minmax(220px,.8fr) 150px;align-items:center;gap:18px;min-height:116px;border:1px solid #dfe5e1;border-radius:10px;padding:12px 56px 12px 10px;background:#fff}.history-card.featured{border-color:#a7c8ad}.history-crop{height:98px;border-right:1px solid #e6e9e7;padding-right:12px}.history-card h3{font-size:17px;font-weight:800}.diagnosis-name{margin-top:5px;font-size:12px}.confidence,.status{display:inline-flex;align-items:center;gap:6px;border-radius:7px;padding:6px 8px;font-size:10px}.confidence{background:#fff7e9;color:#d65816}.confidence svg,.status svg{width:14px;height:14px}.status{background:#eff7ef;color:#0b7130}.status.watch{background:#fff4e5;color:#b65d0a}.created{display:flex;align-items:center;gap:7px;margin-top:12px;font-size:10px;color:#52637a}.created svg{width:15px}.history-follow{min-height:80px;border-left:1px solid #e7eae8;padding-left:18px}.history-follow>p{display:flex;align-items:center;gap:8px;font-size:10px;color:#52637a}.history-follow>p svg{width:17px;color:#08752c}.history-follow>strong{display:block;margin:3px 0 12px 25px;font-size:12px;color:#08752c}.action-progress>span{font-size:9px;color:#52637a}.action-progress>div{display:flex;gap:4px;margin-top:8px}.action-progress i{width:11px;height:11px;border:1px solid #d4dce0;border-radius:50%}.action-progress i.complete{border-color:#08752c;background:#08752c}.history-buttons{display:grid;gap:8px}.history-buttons button{display:flex;height:38px;align-items:center;justify-content:center;gap:7px;border:1px solid #d6ded9;border-radius:7px;font-size:11px}.history-buttons button.primary{border-color:#08752c;background:#08752c;color:#fff}.history-buttons button.primary svg{margin-left:auto}.history-buttons svg{width:15px}.more{position:absolute;right:13px;top:50%;display:grid;width:36px;height:42px;transform:translateY(-50%);place-items:center;border:1px solid #dce2df;border-radius:7px}.more svg{width:18px}
@media(max-width:900px){.history-card{grid-template-columns:150px minmax(0,1fr) 190px;padding:14px 14px 70px;gap:14px}.history-crop{height:190px}.history-follow{border-left:1px solid #e7eae8}.history-buttons{position:absolute;right:14px;bottom:13px;left:14px;grid-template-columns:1fr 1fr}.more{right:12px;top:14px;transform:none}.history-card>div:nth-child(2){padding-right:35px}}
@media(max-width:620px){.history-card{grid-template-columns:145px minmax(0,1fr);padding-bottom:72px}.history-crop{height:195px}.history-follow{grid-column:2;border-left:0;padding-left:0}.history-card h3{font-size:16px}.confidence,.status{font-size:9px}.created{font-size:9px}}
</style>
